def connection_gen(fx, gx, gt, gen_t) -> dict:
    """The committed healed edge-differential construction with E_t REPLACED.

    Byte-for-byte b166.Fixture.connection_for except that the temporal generator
    is an argument.  Gate B pins it: at gen_t = E_t it must reproduce the landed
    fx.edge_d entry for entry, at both sizes.
    """
    local = gx * EX + gt * gen_t
    rt, rx = b105.shift_lifts()
    local_d: dict = {}
    for origin in ORIGINS:
        gauge = (rt ** origin[0]) * (rx ** origin[1])
        block = sp.expand(gauge.H * local * gauge)
        out: dict = {}
        for anchor in fx.chart_cells(origin):
            sites = fx.cell_sites(*anchor)
            for p in range(4):
                for q in range(4):
                    if block[p, q] != 0:
                        key = (sites[p], sites[q])
                        out[key] = out.get(key, 0) + block[p, q]
        local_d[origin] = sclean(out)
    star = sadd(local_d[(0, 0)], sscale(local_d[(1, 0)], -1))
    return {
        (CHART_INDEX[a], CHART_INDEX[b]): sadd(
            local_d[a],
            sscale(
                star,
                HEALING_WEIGHTS[CHART_INDEX[b]] - HEALING_WEIGHTS[CHART_INDEX[a]],
            ),
        )
        for a in ORIGINS
        for b in ORIGINS
    }


def tri(matrix) -> tuple:
    return tuple(inertia(sp.expand(matrix)))


def is_psd(matrix) -> bool:
    n_pos, n_neg, _n_zero = inertia(sp.expand(matrix))
    return n_neg == 0 and n_pos > 0


def blocks_to_dict(fx, blocks: dict) -> dict:
    """A sparse history operator from a dict of (row slice, col slice) blocks."""
    lx = fx.LX
    out: dict = {}
    for (a, b), block in blocks.items():
        for i in range(lx):
            for j in range(lx):
                if block[i, j] != 0:
                    key = (lx * a + i, lx * b + j)
                    out[key] = out.get(key, 0) + block[i, j]
    return sclean(out)


def site_label(fx, c: int):
    """The x-trivial SITE reflection whose fixed slice is c."""
