def slice_map(fx, label) -> tuple:
    lx = fx.LX
    return tuple(sorted({(i // lx, j // lx) for (i, j) in fx.descent(label)}))


# --- the generic two-slice-local families -----------------------------------
def full_block(prefix: str, lx: int):
    return sp.Matrix(lx, lx, lambda i, j: (
        sp.Symbol(f"{prefix}{i}{j}r", real=True)
        + I * sp.Symbol(f"{prefix}{i}{j}i", real=True)
    ))


def generic_blocks(fx, mode: str) -> tuple:
    """Independent generic blocks at EVERY link -- the checker's object.

    mode "herm": Q = Q^H, counted in INDEPENDENT REAL PARAMETERS.
    mode "free": no symmetry at all, counted in FREE SYMBOLS.
    """
    lx, t_phys = fx.LX, fx.PHYS_T
    blocks: dict = {}
    params = 0
    for t in range(t_phys):
        if mode == "herm":
            block = sp.zeros(lx, lx)
            for i in range(lx):
                block[i, i] = sp.Symbol(f"d{t}_{i}{i}r", real=True)
            for i in range(lx):
                for j in range(i + 1, lx):
                    entry = (sp.Symbol(f"d{t}_{i}{j}r", real=True)
                             + I * sp.Symbol(f"d{t}_{i}{j}i", real=True))
                    block[i, j] = entry
                    block[j, i] = sp.conjugate(entry)
            params += lx * lx
        else:
            block = full_block(f"d{t}_", lx)
            params += 2 * lx * lx
        blocks[(t, t)] = block
    for t in range(t_phys):
        nxt = (t + 1) % t_phys
        forward = full_block(f"v{t}_", lx)
        params += 2 * lx * lx
        blocks[(nxt, t)] = forward
        if mode == "herm":
            blocks[(t, nxt)] = forward.H
        else:
            blocks[(t, nxt)] = full_block(f"w{t}_", lx)
            params += 2 * lx * lx
    return blocks, params


def solve_family_blocks(fx):
    """THE SOLVE'S OWN family: ONE shared link block V, SCALAR slice diagonals.

    The solve described this as "fully generic ... 16 free complex symbols".  It
    is neither: it imposes time-translation invariance and scalar diagonals, and
    its real parameter count is measured here rather than quoted.
    """
    lx, t_phys = fx.LX, fx.PHYS_T
    shared = full_block("v", lx)
    blocks: dict = {}
    for t in range(t_phys):
        blocks[(t, t)] = sp.diag(*([sp.Symbol(f"dg_{t}", real=True)] * lx))
        blocks[((t + 1) % t_phys, t)] = shared
        blocks[(t, (t + 1) % t_phys)] = shared.H
    return blocks, shared


def x_local_generic(fx, displacement_two: bool = False, x_local: bool = True):
    """A Hermitian {0,+-1}-local operator, optionally with a displacement-2 term."""
    lx, t_phys = fx.LX, fx.PHYS_T
    blocks: dict = {}
    for t in range(t_phys):
        blocks[(t, t)] = sp.diag(
            *[sp.Symbol(f"dd{t}_{i}", real=True) for i in range(lx)])
    for t in range(t_phys):
        nxt = (t + 1) % t_phys
        if x_local:
            link = sp.diag(
                *[sp.Symbol(f"vv{t}_{i}", real=True) for i in range(lx)])
        else:
            link = sp.Matrix(lx, lx, lambda i, j: sp.Symbol(
                f"vv{t}_{i}{j}", real=True))
        blocks[(nxt, t)] = link
        blocks[(t, nxt)] = link.H
    if displacement_two:
        for t in range(t_phys):
            far = (t + 2) % t_phys
            jump = sp.Matrix(lx, lx, lambda i, j: sp.Symbol(
                f"gg{t}_{i}{j}", real=True))
            blocks[(far, t)] = blocks.get((far, t), sp.zeros(lx, lx)) + jump
            blocks[(t, far)] = blocks.get((t, far), sp.zeros(lx, lx)) + jump.H
    return blocks


# --- THE IMPOSED NULL MODEL -- reference-imposed, NOT a framework object -----
def cayley_cs(half_tangent):
    """(cos, sin) of the angle whose half-tangent is t -- exactly rational."""
    value = sp.sympify(half_tangent)
    return ((1 - value ** 2) / (1 + value ** 2), 2 * value / (1 + value ** 2))


def cayley_phase(sigma):
    """A unimodular element of Q(i): u = (1 + i s/2)/(1 - i s/2)."""
    value = sp.sympify(sigma)
    return sp.expand(sp.simplify((1 + I * value / 2) / (1 - I * value / 2)))


def pair_unitary(lx: int, pairs, block):
    out = sp.eye(lx)
    for (i, j) in pairs:
        out[i, i] = block[0, 0]
        out[i, j] = block[0, 1]
        out[j, i] = block[1, 0]
        out[j, j] = block[1, 1]
    return out


def qca_step(lx: int, mass, s_t, sigma):
    """THE IMPOSED STEP -- REFERENCE-IMPOSED, NOT DERIVED, NOT A FRAMEWORK OBJECT.

    A free staggered (partitioned) quantum-walk step on the SAME slice space the
    framework's quotient gives: even links {(0,1),(2,3),...} and odd links
    {(1,2),...,(L_x-1,0)}, the exactly-unitary Cayley transport block, the
    standard Dirac-walk mass coin on the even partition, U = M U_odd U_even.
    """
    cos_t, sin_t = cayley_cs(sp.sympify(s_t) / 2)
    phase = cayley_phase(sigma)
    block = sp.Matrix([[cos_t, -sp.conjugate(phase) * sin_t],
                       [phase * sin_t, cos_t]])
    cos_m, sin_m = cayley_cs(sp.sympify(mass) / 2)
    coin = sp.Matrix([[cos_m, -I * sin_m], [-I * sin_m, cos_m]])
    even = [(k, k + 1) for k in range(0, lx, 2)]
    odd = [(k, (k + 1) % lx) for k in range(1, lx, 2)]
    return sp.expand(
        pair_unitary(lx, even, coin)
        * pair_unitary(lx, odd, block)
        * pair_unitary(lx, even, block)
    )


def qca_history(fx, mass, s_t, sigma, carrier_sub: dict, wrap_sign: int = -1):
    """The IMPOSED two-slice-local history operator.  NOT a framework object."""
    lx, t_phys = fx.LX, fx.PHYS_T
    step = qca_step(lx, mass, s_t, sigma)
    dagger = step.H
    trace_d = b166.hodge_trace_D(fx)
    out: dict = {}
    for t in range(t_phys):
        for x in range(lx):
            value = sp.expand(
                sp.sympify(mass)
                * sp.expand(trace_d[(t, x)]).subs(carrier_sub))
            if value != 0:
                out[(lx * t + x, lx * t + x)] = value
    for t in range(t_phys):
        nxt = (t + 1) % t_phys
        sign = wrap_sign if nxt == 0 else 1
        for y in range(lx):
            for x in range(lx):
                if step[y, x] != 0:
                    key = (lx * nxt + y, lx * t + x)
                    out[key] = out.get(key, 0) + sign * step[y, x]
                if dagger[x, y] != 0:
                    key = (lx * t + x, lx * nxt + y)
                    out[key] = out.get(key, 0) + sign * dagger[x, y]
    return sclean(out), step


