@dataclass(frozen=True)
class Facts:
    main_head: str
    authority: AuthorityCertificate
    convention: tuple        # B: the banner, and the rebuild anchor
    contrast: tuple          # C: the contrast table
    corner: tuple            # D: the corner theorem
    refutation: tuple        # E: the cancellation dictionary and the witnesses
    loopholes: tuple         # F: the census
    freezing: tuple          # G: the region pin, and the generator sweep
    deep: bool
    exact_no_float: bool
    scope: dict


# ---------------------------------------------------------------------------
# B. THE CONVENTION COLLISION, measured on identical matrices
# ---------------------------------------------------------------------------
def convention_probe() -> tuple:
    return b166.convention_probe()


# ---------------------------------------------------------------------------
# C. THE CONTRAST TABLE -- framework versus the REFERENCE-IMPOSED null model
# ---------------------------------------------------------------------------
def bench_substitution(fx, c: int) -> dict:
    sub = b166.carrier_substitution(fx, b166.graded_carrier(fx, c, CARRIER_SIGMA))
    sub[SX] = BENCH_SX
    sub[MASS] = BENCH_MASS
    return sub


def contrast_probe(fx) -> dict:
    lx, c = fx.LX, SLICE_C
    t_phys = fx.PHYS_T
    label = site_label(fx, c)
    rows = fx.slice_rows(c, c + 1)
    sub = bench_substitution(fx, c)

    # --- the FRAMEWORK column, on the ACTION ---------------------------------
    pin = b166.region_pin(fx, [c - 1, c])
    hodge = b166.ssubs(fx.H_free, pin)
    action = fx.quotient_action(fx.edge_d[(0, 0)], hodge, MASS)
    full = dense(action, fx.PHYS, fx.PHYS)
    outgoing = sp.expand(full[fx.slice_rows((c + 1) % t_phys), fx.slice_rows(c)])
    pairing, _ = b166.region_pairing(fx, c, fx.edge_d[(0, 0)], [c - 1, c])
    flat = sp.expand(sp.expand(pairing.subs({ST: 0})).subs(sub))
    live = sp.expand(sp.expand(pairing.subs({ST: BENCH_ST})).subs(sub))
    cross = sp.expand(pairing[:lx, lx:])
    c_one = sp.expand(cross.diff(ST))
    twisted = sp.expand(
        sp.expand((cross.subs({ST: -ST})).H * cross)
        .subs({ST: BENCH_ST}).subs(sub))
    want = sp.expand(
        sp.expand(-ST ** 2 * c_one.H * c_one).subs({ST: BENCH_ST}).subs(sub))

    # --- the off-region control (the same block, unpinned) -------------------
    off_action = fx.quotient_action(fx.edge_d[(0, 0)], fx.H_free, MASS)
    off_full = dense(off_action, fx.PHYS, fx.PHYS)
    off_sub = b166.carrier_substitution(
        fx, {key: (CARRIER_SIGMA, R(1, 2)) for key in fx.CELLS})
    off_sub[SX] = BENCH_SX
    off_sub[MASS] = BENCH_MASS
    off_w = sp.expand(
        off_full[fx.slice_rows((c + 1) % t_phys), fx.slice_rows(c)]
        .subs({ST: BENCH_ST}).subs(off_sub))

    # --- the REFERENCE-IMPOSED null-model column -----------------------------
    unitary = 0
    full_rank = 0
    doubled_positive = 0
    hollow = 0
    inertias = set()
    for (mass, s_t, sigma) in NULL_GRID:
        history, step = qca_history(fx, mass, s_t, sigma, sub)
        gram = sp.expand(step.H * step)
        if gram == sp.eye(lx):
            unitary += 1
        if step.rank() == lx:
            full_rank += 1
        if tri(gram) == NULL_DOUBLED_INERTIA:
            doubled_positive += 1
        paired = fx.pairing(fx.descent(label), history, rows)
        inertias.add(tri(paired))
        if sp.expand(paired[lx:, lx:]) == sp.zeros(lx, lx):
            hollow += 1

    trace_d = b166.hodge_trace_D(fx)
    gram_c = sp.diag(*[sp.expand(trace_d[(c, x)]).subs(sub) for x in range(lx)])
    gram_c1 = sp.diag(*[sp.expand(trace_d[((c + 1) % t_phys, x)]).subs(sub)
                        for x in range(lx)])
    step_bench = qca_step(lx, BENCH_MASS, BENCH_ST, CARRIER_SIGMA)
    gram_trace = sp.simplify(
        sp.trace(gram_c.inv() * step_bench.H * gram_c1 * step_bench))

    return {
        "framework_w_symbolically_zero": outgoing == sp.zeros(lx, lx),
        "framework_flat": tri(flat),
        "framework_live": tri(live),
        "framework_corner_hollow":
            sp.expand(live[lx:, lx:]) == sp.zeros(lx, lx),
        "framework_doubled": tri(twisted),
        "framework_doubled_identity":
            sp.expand(twisted - want) == sp.zeros(lx, lx),
        "rank_c1": sp.expand(c_one.subs(sub)).rank(),
        "off_region_rank": off_w.rank(),
        "landed_control_trace": b166.CONTROL_TRACE[fx.tag],
        "null_unitary": unitary,
        "null_full_rank": full_rank,
        "null_doubled_positive": doubled_positive,
        "null_corner_hollow": hollow,
        "null_inertias": tuple(sorted(inertias)),
        "null_identity_at_origin": qca_step(lx, 0, 0, 0) == sp.eye(lx),
        "gram_trace": gram_trace,
        "grid_points": len(NULL_GRID),
    }


# ---------------------------------------------------------------------------
# D. THE CORNER THEOREM, at its checker-corrected scope
# ---------------------------------------------------------------------------
def corner_census() -> tuple:
    """The corner at T_phys = 2..6 on L_x = 2.  LIVE at 2 and 3 -- measured."""
    out = []
    for t_phys, _expected in CORNER_T_CENSUS:
        fx = b166.Fixture(2 * t_phys, CORNER_CENSUS_LX, f"{2 * t_phys}x2")
        lx, c = fx.LX, min(SLICE_C, fx.PHYS_T - 1)
        label = site_label(fx, c)
        blocks = x_local_generic(fx)
        paired = fx.pairing(fx.descent(label),
                            blocks_to_dict(fx, blocks),
                            fx.slice_rows(c, c + 1))
        out.append((t_phys,
                    sp.expand(paired[lx:, lx:]) == sp.zeros(lx, lx)))
    return tuple(out)


def corner_probe(fx, deep: bool) -> dict:
    lx, c, t_phys = fx.LX, SLICE_C, fx.PHYS_T
    label = site_label(fx, c)
    rows = fx.slice_rows(c, c + 1)

    modes = ("herm", "free") if deep else ("herm",)
    generality = {}
    for mode in modes:
        blocks, params = generic_blocks(fx, mode)
        history = blocks_to_dict(fx, blocks)
        symbols: set = set()
        for value in history.values():
            symbols |= sp.sympify(value).free_symbols
        paired = fx.pairing(fx.descent(label), history, rows)
        generality[mode] = (
            params,
            len(symbols),
            sp.expand(paired[lx:, lx:]) == sp.zeros(lx, lx),
            sp.expand(paired[:lx, lx:]) != sp.zeros(lx, lx),
        )

    # THE SOLVE'S OWN FAMILY, counted rather than described
    blocks, _shared = solve_family_blocks(fx)
    family = blocks_to_dict(fx, blocks)
    family_symbols: set = set()
    for value in family.values():
        family_symbols |= sp.sympify(value).free_symbols

    # the corner IS the displacement-2 block, and only that
    reflect = {a: b for (a, b) in slice_map(fx, label)}
    return {
        "generality": generality,
        "solve_family_params": len(family_symbols),
        "corner_is_displacement_two":
            reflect[(c + 1) % t_phys] == (c - 1) % t_phys,
        "reflect": tuple(sorted(reflect.items())),
        "even_p_t": label[1] % 2 == 0,
    }


# ---------------------------------------------------------------------------
# E. THE REFUTATION -- the block dictionary and the connected PSD witnesses
# ---------------------------------------------------------------------------
WITNESS_A = sp.Matrix([[1, 2, 0, 0], [0, 3, 1, 0], [0, 0, 5, 2], [1, 0, 0, 7]])
WITNESS_DIAG = sp.diag(3, 5, 7, 11)


def refutation_probe(fx) -> dict:
    lx, c, t_phys = fx.LX, SLICE_C, fx.PHYS_T
    label = site_label(fx, c)
    rows = fx.slice_rows(c, c + 1)

    # (1) THE BLOCK DICTIONARY, on a FULLY NON-HERMITIAN generic operator
    blocks, _params = generic_blocks(fx, "free")
    paired = fx.pairing(fx.descent(label), blocks_to_dict(fx, blocks), rows)
    want_c = sp.expand(
        (blocks[(c, (c + 1) % t_phys)] + blocks[((c - 1) % t_phys, c)].H) / 2)
    want_diag = sp.expand((blocks[(c, c)] + blocks[(c, c)].H) / 2)
    dictionary = (
        sp.expand(sp.expand(paired[:lx, lx:]) - want_c) == sp.zeros(lx, lx)
        and sp.expand(sp.expand(paired[:lx, :lx]) - want_diag)
        == sp.zeros(lx, lx)
    )

    # (2) THE HOLLOW-CORNER LEMMA, on explicit blocks -- rank 0, 1 and L_x
    lemma = []
    for rank, _expected in LEMMA_RANKS:
        cross = sp.zeros(lx, lx)
        for k in range(rank):
            cross[k, k] = R(1, 100) * (k + 1)
        block = sp.Matrix(sp.BlockMatrix(
            [[WITNESS_DIAG, cross], [cross.H, sp.zeros(lx, lx)]]))
        lemma.append((rank, tri(block)))

    # (3) WITNESS 1 -- Y = -X^H: CONNECTED both ways, C = 0, PSD
    blocks = {t: None for t in range(t_phys)}
    witness = {(t, t): WITNESS_DIAG for t in range(t_phys)}
    witness[((c + 1) % t_phys, c)] = WITNESS_A
    witness[(c, (c + 1) % t_phys)] = WITNESS_A.H
    witness[(c, (c - 1) % t_phys)] = sp.expand(-WITNESS_A.H)
    witness[((c - 1) % t_phys, c)] = sp.expand(-WITNESS_A)
    paired_one = fx.pairing(fx.descent(label), blocks_to_dict(fx, witness), rows)
    witness_one = (
        WITNESS_A.rank(),
        sp.expand(-WITNESS_A.H).rank(),
        sp.expand(paired_one[:lx, lx:]) == sp.zeros(lx, lx),
        sp.expand(paired_one[lx:, lx:]) == sp.zeros(lx, lx),
        tri(paired_one),
    )

    # (4) WITNESS 2 -- INSIDE THE SOLVE'S OWN FAMILY: C == herm(V) identically
    blocks, shared = solve_family_blocks(fx)
    paired_family = fx.pairing(
        fx.descent(label), blocks_to_dict(fx, blocks), rows)
    identity = sp.expand(
        sp.expand(paired_family[:lx, lx:]) - sp.expand((shared + shared.H) / 2)
    ) == sp.zeros(lx, lx)
    rows_v = []
    for name, value in (("i*1", I * sp.eye(lx)),
                        ("i*diag(1,2,3,5)", I * sp.diag(1, 2, 3, 5)),
                        ("1", sp.eye(lx))):
        witness = {(t, t): WITNESS_DIAG for t in range(t_phys)}
        for t in range(t_phys):
            witness[((t + 1) % t_phys, t)] = value
            witness[(t, (t + 1) % t_phys)] = value.H
        paired_v = fx.pairing(
            fx.descent(label), blocks_to_dict(fx, witness), rows)
        rows_v.append((
            name,
            value.rank(),
            sp.expand(paired_v[:lx, lx:]) == sp.zeros(lx, lx),
            tri(paired_v),
        ))

    # (5) the CANCELLATION LOCUS: C == 0 <=> V anti-Hermitian, 16 of 32 real
    anti = sp.expand(shared + shared.H)
    equations = set()
    for entry in anti:
        equations |= {sp.expand(sp.re(entry)), sp.expand(sp.im(entry))}
    equations = {e for e in equations if e != 0}
    free = sorted({str(s) for s in shared.free_symbols})
    locus = len(free) - sp.Matrix(
        [[sp.diff(e, sp.Symbol(name, real=True)) for name in free]
         for e in sorted(equations, key=str)]).rank()

    return {
        "dictionary": dictionary,
        "lemma": tuple(lemma),
        "witness_one": witness_one,
        "family_identity": identity,
        "witness_two": tuple(rows_v),
        "v_space_dim": len(free),
        "cancellation_locus_dim": locus,
    }


# ---------------------------------------------------------------------------
# F. THE LOOPHOLE CENSUS -- at least TWO, and x-non-locality is not one
# ---------------------------------------------------------------------------
def loophole_probe(fx) -> dict:
    lx, c, t_phys = fx.LX, SLICE_C, fx.PHYS_T
    label = site_label(fx, c)
    rows = fx.slice_rows(c, c + 1)

    base = blocks_to_dict(fx, x_local_generic(fx))
    paired_base = fx.pairing(fx.descent(label), base, rows)

    # (1) DISPLACEMENT 2 -- genuinely fills the corner, and ONLY the corner
    wide = blocks_to_dict(fx, x_local_generic(fx, displacement_two=True))
    paired_wide = fx.pairing(fx.descent(label), wide, rows)
    corner = sp.expand(paired_wide[lx:, lx:])
    entries = sum(1 for i in range(lx) for j in range(lx) if corner[i, j] != 0)
    surgical = (
        sp.expand(sp.expand(paired_wide[:lx, :lx])
                  - sp.expand(paired_base[:lx, :lx])) == sp.zeros(lx, lx)
        and sp.expand(sp.expand(paired_wide[:lx, lx:])
                      - sp.expand(paired_base[:lx, lx:])) == sp.zeros(lx, lx)
    )

    # (2) LINK REFLECTIONS -- a SECOND escape, on the generic object AND on the
    #     committed region action, where none of them reaches PSD
    links = link_labels_x_trivial(fx)
    generic_live = 0
    for link in links:
        paired = fx.pairing(fx.descent(link), base, rows)
        if sp.expand(paired[lx:, lx:]) != sp.zeros(lx, lx):
            generic_live += 1
    sub = bench_substitution(fx, c)
    pin = b166.region_pin(fx, [c - 1, c])
    action = fx.quotient_action(
        fx.edge_d[(0, 0)], b166.ssubs(fx.H_free, pin), MASS)
    region_live = 0
    region_psd = 0
    region_inertias = set()
    for link in links:
        paired = sp.expand(
            fx.pairing(fx.descent(link), action, rows)
            .subs({ST: BENCH_ST}).subs(sub))
        if sp.expand(paired[lx:, lx:]) != sp.zeros(lx, lx):
            region_live += 1
        region_inertias.add(tri(paired))
        if is_psd(paired):
            region_psd += 1

    # (3) x-NON-LOCALITY IS NOT AN ESCAPE
    dense_x = blocks_to_dict(fx, x_local_generic(fx, x_local=False))
    paired_x = fx.pairing(fx.descent(label), dense_x, rows)

    # (4) the WIDER support is LESS permissive, not more
    rows_three = fx.slice_rows(c - 1, c, c + 1)
    paired_three = fx.pairing(fx.descent(label), base, rows_three)
    diagonal_hollow = tuple(
        sp.expand(paired_three[k * lx:(k + 1) * lx, k * lx:(k + 1) * lx])
        == sp.zeros(lx, lx)
        for k in range(3)
    )

    return {
        "disp2_entries": entries,
        "disp2_surgical": surgical,
        "link_labels": len(links),
        "link_generic_live": generic_live,
        "link_region_live": region_live,
        "link_region_psd": region_psd,
        "link_region_inertias": tuple(sorted(region_inertias)),
        "x_nonlocal_hollow":
            sp.expand(paired_x[lx:, lx:]) == sp.zeros(lx, lx),
        "wider_support_hollow": diagonal_hollow,
    }


# ---------------------------------------------------------------------------
# G. THE FREEZING, REFINED -- and the generator sweep at its settled scope
# ---------------------------------------------------------------------------
def freezing_probe(fx) -> dict:
    lx, c, t_phys = fx.LX, SLICE_C, fx.PHYS_T
    pin = b166.region_pin(fx, [c - 1, c])
    action = fx.quotient_action(
        fx.edge_d[(0, 0)], b166.ssubs(fx.H_free, pin), MASS)
    full = dense(action, fx.PHYS, fx.PHYS)
    sub = bench_substitution(fx, c)

    tables = {}
    for value in BASELINE_ST:
        matrix = sp.expand(full.subs({ST: value}).subs(sub))
        tables[value] = tuple(
            tuple(sp.expand(
                matrix[fx.slice_rows(row), fx.slice_rows(col)]).rank()
                for col in range(t_phys))
            for row in range(t_phys)
        )

    forward = sp.expand(full[fx.slice_rows((c + 1) % t_phys), fx.slice_rows(c)])
    backward = sp.expand(full[fx.slice_rows(c), fx.slice_rows((c + 1) % t_phys)])
    off_action = fx.quotient_action(fx.edge_d[(0, 0)], fx.H_free, MASS)
    off_full = dense(off_action, fx.PHYS, fx.PHYS)
    off_sub = b166.carrier_substitution(
        fx, {key: (CARRIER_SIGMA, R(1, 2)) for key in fx.CELLS})
    off_sub[SX] = BENCH_SX
    off_sub[MASS] = BENCH_MASS
    off_forward = sp.expand(
        off_full[fx.slice_rows((c + 1) % t_phys), fx.slice_rows(c)]
        .subs({ST: BENCH_ST}).subs(off_sub))

    flat = tables[sp.Integer(0)]
    live = tables[BENCH_ST]
    return {
        "table_flat": flat,
        "table_live": live,
        "row_dead": all(flat[c][s] == 0 for s in range(t_phys) if s != c),
        "column_dead": all(flat[r][c] == 0 for r in range(t_phys) if r != c),
        "future_dead_both_ways":
            forward == sp.zeros(lx, lx) and backward == sp.zeros(lx, lx),
        "past_live_both_ways":
            live[c][(c - 1) % t_phys] == lx and live[(c - 1) % t_phys][c] == lx,
        "off_region_forward_rank": off_forward.rank(),
        "action_hermitian":
            sp.expand(full - full.H) == sp.zeros(fx.PHYS, fx.PHYS),
    }


def basis_32() -> tuple:
    out = []
    for kind, multiplier in (("re", sp.Integer(1)), ("im", I)):
        for p in range(4):
            for q in range(4):
                cell = sp.zeros(4, 4)
                cell[p, q] = multiplier
                out.append(((p, q), kind, cell))
    return tuple(out)


def generator_probe(fx) -> dict:
    lx, c = fx.LX, SLICE_C
    sub = bench_substitution(fx, c)

    columns_symbolic = []
    columns_numeric = []
    complex_symbolic = []
    complex_numeric = []
    odd = 0
    b_free = 0
    live_positions = set()
    hollow_symbolic = 0
    hollow_bench = 0
    for (position, kind, cell) in basis_32():
        pairing, _ = b166.region_pairing(
            fx, c, connection_gen(fx, I * SX, I * ST, cell)[(0, 0)], [c - 1, c])
        cross = sp.expand(pairing[:lx, lx:])
        c_one = sp.expand(cross.diff(ST))
        block_b = sp.expand(pairing[:lx, :lx])
        if (sp.expand(cross.subs({ST: 0})) == sp.zeros(lx, lx)
                and sp.expand(cross - ST * c_one) == sp.zeros(lx, lx)):
            odd += 1
        if sp.expand(block_b.diff(ST)) == sp.zeros(lx, lx):
            b_free += 1
        if c_one != sp.zeros(lx, lx):
            live_positions.add(position)
        corner = sp.expand(pairing[lx:, lx:])
        if corner == sp.zeros(lx, lx):
            hollow_symbolic += 1
        if sp.expand(corner.subs(sub)) == sp.zeros(lx, lx):
            hollow_bench += 1
        numeric = sp.expand(c_one.subs(sub))
        columns_symbolic.append([
            part for i in range(lx) for j in range(lx)
            for part in (sp.expand(sp.re(c_one[i, j])),
                         sp.expand(sp.im(c_one[i, j])))])
        columns_numeric.append([
            part for i in range(lx) for j in range(lx)
            for part in (sp.expand(sp.re(numeric[i, j])),
                         sp.expand(sp.im(numeric[i, j])))])
        if kind == "re":
            complex_symbolic.append(
                [c_one[i, j] for i in range(lx) for j in range(lx)])
            complex_numeric.append(
                [numeric[i, j] for i in range(lx) for j in range(lx)])

    matrix_symbolic = sp.Matrix(columns_symbolic).T
    matrix_numeric = sp.Matrix(columns_numeric).T
    hop = [k for k, (position, _kind, _cell) in enumerate(basis_32())
           if position in LIVE_POSITIONS]
    settlement_symbolic = (
        matrix_symbolic.rank(),
        GEN_BASIS_DIM - matrix_symbolic.rank(),
        matrix_symbolic[:, hop].rank(),
        sp.Matrix(complex_symbolic).T.rank(),
    )
    settlement_numeric = (
        matrix_numeric.rank(),
        GEN_BASIS_DIM - matrix_numeric.rank(),
        matrix_numeric[:, hop].rank(),
        sp.Matrix(complex_numeric).T.rank(),
    )

    # THE B167 CHECKER'S HOP-CARRYING KERNEL WITNESS, SOLVED rather than quoted
    ratio = sp.Symbol("kappa_hop", real=True)
    e02 = sp.zeros(4, 4)
    e02[0, 2] = 1
    e20 = sp.zeros(4, 4)
    e20[2, 0] = 1
    pairing, _ = b166.region_pairing(
        fx, c,
        connection_gen(fx, I * SX, I * ST, e02 + ratio * e20)[(0, 0)],
        [c - 1, c])
    c_one = sp.expand(sp.expand(pairing[:lx, lx:]).diff(ST).subs(sub))
    equations = set()
    for entry in c_one:
        equations |= {sp.expand(sp.re(entry)), sp.expand(sp.im(entry))}
    equations = {e for e in equations if e != 0}
    solutions = sp.solve(sorted(equations, key=str), ratio, dict=True)
    killed = solutions[0][ratio] if solutions else None
    witness_inertias = ()
    if killed is not None:
        base = sp.expand(pairing.subs({ratio: killed}).subs(sub))
        witness_inertias = tuple(
            tri(sp.expand(base.subs({ST: value}))) for value in BASELINE_ST)

    return {
        "basis": GEN_BASIS_DIM,
        "odd": odd,
        "b_free": b_free,
        "live_positions": tuple(sorted(live_positions)),
        "hollow_symbolic": hollow_symbolic,
        "hollow_bench": hollow_bench,
        "settlement_symbolic": settlement_symbolic,
        "settlement_numeric": settlement_numeric,
        "hop_directions": len(hop),
        "kernel_ratio": killed,
        "kernel_witness_inertias": witness_inertias,
    }


NAMED_GENERATORS = (
    ("E_t                (committed control, NILPOTENT)", lambda: ET),
    ("E_t + E_t^T        (symmetric hop)", lambda: ET + ET.T),
    ("E_t + 2 J_3        (hop + Cartan)", lambda: ET + sp.diag(-1, -1, 1, 1)),
    ("E_t + 1            (hop + the QCA's stay-put term)",
     lambda: ET + sp.eye(4)),
    ("E_t E_t^T + E_t    (idempotent hop-projector)", lambda: ET + ET * ET.T),
    ("i (E_t - E_t^T)    (anti-Hermitian hop)", lambda: I * (ET - ET.T)),
    ("2 J_3              (pure Cartan, NO hop)", lambda: sp.diag(-1, -1, 1, 1)),
)


def named_generator_probe(fx, deep: bool) -> tuple:
    lx, c = fx.LX, SLICE_C
    sub = bench_substitution(fx, c)
    grid = DEEP_ST if deep else BASELINE_ST
    out = []
    for name, builder in NAMED_GENERATORS:
        generator = builder()
        pairing, _ = b166.region_pairing(
            fx, c,
            connection_gen(fx, I * SX, I * ST, generator)[(0, 0)],
            [c - 1, c])
        base = sp.expand(pairing.subs(sub))
        rank = sp.expand(
            sp.expand(pairing[:lx, lx:]).diff(ST).subs(sub)).rank()
        inertias = tuple(
            tri(sp.expand(base.subs({ST: value}))) for value in grid)
        out.append((
            name,
            sp.expand(generator * generator) == sp.zeros(4, 4),
            rank,
            inertias,
        ))
    return tuple(out)


def et_support_probe(fx) -> dict:
    half = fx.COVER_T // 2
    lx = fx.LX
    edge = fx.edge_d[(0, 0)]
    cover = tuple(sorted({
        (((j // lx) - (i // lx) + half) % fx.COVER_T) - half
        for (i, j) in edge
    }))
    cells = tuple(sorted(
        (p, q) for p in range(4) for q in range(4) if ET[p, q] != 0))
    return {"cover_support": cover, "cell_entries": cells}


# ---------------------------------------------------------------------------
# measured facts (computed once, before any mutation flag is consulted)
# ---------------------------------------------------------------------------
def measure(deep: bool) -> Facts:
    main_head = git_output("rev-parse", "origin/main")
    authority = authority_certificate(main_head)

    fixtures = {tag: b166.Fixture(cover_t, lx, tag)
                for tag, cover_t, lx in FIXTURE_SPECS}

    # ---------------------------------------------------------------- B ----
    anchor = tuple(
        all(
            sclean(sadd(
                connection_gen(fixtures[tag], I * SX, I * ST, ET)[key],
                sscale(fixtures[tag].edge_d[key], -1),
            )) == {}
            for key in fixtures[tag].EDGE_KEYS
        )
        for tag in TAGS
    )
    pairs, landed_psd, here_psd, orders_differ = convention_probe()
    convention = (
        pairs, landed_psd, here_psd, orders_differ, anchor,
        tuple(len(fixtures[tag].involutive) for tag in TAGS),
        tuple(len(fixtures[tag].x_trivial) for tag in TAGS),
    )

    # ---------------------------------------------------------------- C ----
    contrast = {tag: contrast_probe(fixtures[tag]) for tag in TAGS}

    # ---------------------------------------------------------------- D ----
    census = corner_census()
    corner = {tag: corner_probe(fixtures[tag], deep) for tag in TAGS}

    # ---------------------------------------------------------------- E ----
    refutation = {tag: refutation_probe(fixtures[tag]) for tag in TAGS}

    # ---------------------------------------------------------------- F ----
    loopholes = {tag: loophole_probe(fixtures[tag]) for tag in TAGS}

    # ---------------------------------------------------------------- G ----
    freezing = {tag: freezing_probe(fixtures[tag]) for tag in TAGS}
    # THE FIRST HEAVY: the full 32-direction generator basis.  The baseline runs
    # it at 12x4 only; --deep adds 8x4 and with it the 25/32 vs 26/32 census.
    sweep_tags = TAGS if deep else ("12x4",)
    generators = {tag: generator_probe(fixtures[tag]) for tag in sweep_tags}
    named = {tag: named_generator_probe(fixtures[tag], deep) for tag in TAGS}
    et_support = {tag: et_support_probe(fixtures[tag]) for tag in TAGS}

    scalars: list = (
        [contrast[tag]["gram_trace"] for tag in TAGS]
        + [contrast[tag]["landed_control_trace"] for tag in TAGS]
        + [generators[tag]["kernel_ratio"] for tag in sweep_tags]
        + [GRAM_TRACE, LANDED_CONTROL_TRACE]
        + list(KERNEL_RATIO.values())
    )
    exact = all(no_float(value) for value in scalars)

    return Facts(
        main_head=main_head,
        authority=authority,
        convention=convention,
        contrast=tuple((tag, contrast[tag]) for tag in TAGS),
        corner=(census, tuple((tag, corner[tag]) for tag in TAGS)),
        refutation=tuple((tag, refutation[tag]) for tag in TAGS),
        loopholes=tuple((tag, loopholes[tag]) for tag in TAGS),
        freezing=(tuple((tag, freezing[tag]) for tag in TAGS),
                  tuple((tag, generators[tag]) for tag in sweep_tags),
                  tuple((tag, named[tag]) for tag in TAGS),
                  tuple((tag, et_support[tag]) for tag in TAGS)),
        deep=deep,
        exact_no_float=exact,
        scope=scope_certificate(raw_note()),
    )


