# ---------------------------------------------------------------------------
# claims: the only thing a mutation is allowed to touch
# ---------------------------------------------------------------------------
CONVENTION_KEYS = ("convention_banner", "convention_hazard_order",
                   "convention_collision_named", "convention_audit_teeth",
                   "neither_helper_wrong")
NULL_MODEL_KEYS = ("null_model_reference_imposed", "null_model_not_framework",
                   "two_currencies", "different_axes")
REFRAME_KEYS = ("psd_iff_disconnection_struck", "reframe_does_not_follow",
                "supervisor_language_corrected",
                "disconnection_sufficient_not_necessary")


def build_claims(mutation: str) -> dict:
    claims: dict = {
        "main_head": CURRENT_MAIN,
        "parent_pin": "resolved",
        "lane_conventions_uniform": False,
        "null_pairing_inertia": NULL_PAIRING_INERTIA,
        "unitary_step_is_os_positive": False,
        "corner_hollow_at_site_reflections": True,
        "corner_hollow_min_t": 4,
        "psd_iff_disconnection": False,
        "dictionary_holds": True,
        "loophole_count": LOOPHOLE_COUNT,
        "future_link_dead_both_ways": True,
        "rank_settlement_symbolic": RANK_SETTLEMENT_SYMBOLIC,
        "required_scope_keys": SCOPE_KEYS,
    }
    if mutation == "stale_main_authority":
        claims["main_head"] = STALE_MAIN
    elif mutation == "stale_parent_authority":
        claims["parent_pin"] = "stale"
    elif mutation == "claim_convention_uniform":
        # THE BANNER DENIED: the lane asserted to carry ONE inertia convention,
        # which the two-helper comparison on identical matrices forbids
        claims["lane_conventions_uniform"] = True
    elif mutation == "break_contrast_table":
        # THE CONTRAST TABLE DENIED at its sharpest cell: the imposed unitary's
        # framework-functor pairing asserted PSD, which 8 of 8 (4,4,0) forbids
        claims["null_pairing_inertia"] = FRAMEWORK_FLAT_INERTIA
    elif mutation == "claim_unitary_is_os_positive":
        # THE CATEGORY ERROR RE-INTRODUCED: a real-time unitary step asserted to
        # be an OS-positive object, which the 8-point census forbids
        claims["unitary_step_is_os_positive"] = True
    elif mutation == "break_corner_theorem":
        # WHAT SURVIVES DENIED: the corner asserted NOT hollow at a site
        # reflection, which the fully non-Hermitian measurement forbids
        claims["corner_hollow_at_site_reflections"] = False
    elif mutation == "claim_corner_hollow_at_every_t":
        # THE MISSING HYPOTHESIS RE-INTRODUCED: the solve's "at ANY T_phys",
        # which the live corners at T_phys = 2 and 3 forbid
        claims["corner_hollow_min_t"] = 2
    elif mutation == "claim_psd_iff_disconnection":
        # THE STRUCK HEADLINE RE-ASSERTED: "PSD <=> disconnection", which the
        # connected rank-4 PSD witnesses forbid at both sizes
        claims["psd_iff_disconnection"] = True
    elif mutation == "break_cancellation_dictionary":
        # THE DICTIONARY DENIED: C asserted NOT to be the reflected combination
        # (Q[c,c+1] + Q[c-1,c]^H)/2, which the symbolic identity forbids
        claims["dictionary_holds"] = False
    elif mutation == "claim_one_loophole":
        # THE SOLVE'S HANDOFF RE-ASSERTED: "the ONE surviving loophole", which
        # the live link-reflection corners forbid
        claims["loophole_count"] = 1
    elif mutation == "claim_freezing_one_sided":
        # THE IMPRECISE PHRASING RE-ASSERTED: one DIRECTION of the future link
        # claimed to survive, which the symbolic double vanishing forbids
        claims["future_link_dead_both_ways"] = False
    elif mutation == "break_rank_settlement":
        # THE SETTLEMENT DENIED at its symbolic half: the real rank of G -> C1
        # asserted to be 8 symbolically, which the symbolic measurement forbids
        claims["rank_settlement_symbolic"] = RANK_SETTLEMENT_NUMERIC
    elif mutation == "claim_null_model_framework":
        # THE DISCIPLINE DROPPED: the note allowed to present the imposed
        # unitary as a framework object rather than a REFERENCE-IMPOSED one
        claims["required_scope_keys"] = tuple(
            key for key in SCOPE_KEYS if key not in NULL_MODEL_KEYS
        )
    elif mutation == "drop_reframe_correction":
        # THE CORRECTION DROPPED: the note allowed to omit the striking of
        # "PSD <=> disconnection" and the correction of the reframe
        claims["required_scope_keys"] = tuple(
            key for key in SCOPE_KEYS if key not in REFRAME_KEYS
        )
    elif mutation == "drop_n5_fence":
        claims["required_scope_keys"] = tuple(
            key for key in SCOPE_KEYS if key != "n5_verbatim"
        )
    return claims


# ---------------------------------------------------------------------------
# gates: pure functions of the measured facts and the claims
# ---------------------------------------------------------------------------
def evaluate_gates(facts: Facts, claims: dict, elapsed_ns: int) -> dict:
    authority = facts.authority
    parent_blobs_ok = (
        authority.parent_artifact_blobs
        if claims["parent_pin"] == "resolved"
        else authority.stale_parent_artifact_blobs
    )
    gate_a = bool(
        AUDIT_INPUT_PATHS
        == (
            "docs/ADMISSIBILITY_DIRAC_KAHLER_NULL_MODEL_CORNER_THEOREM_BOUNDED_THEOREM_NOTE_2026-08-21.md",
            "docs/MINIMAL_AXIOMS_2026-06-29.md",
            "docs/audit/data/axiom_premise_nodes.json",
            "docs/ADMISSIBILITY_DIRAC_KAHLER_INTERPRETATION_DISCRIMINATORS_BOUNDED_THEOREM_NOTE_2026-08-21.md",
            "scripts/admissibility_dirac_kahler_interpretation_discriminators_2026_08_21.py",
        )
        and PARENT_ARTIFACTS == (BLOCK166_NOTE, BLOCK166_RUNNER)
        and len(PARENT_ARTIFACT_BLOBS) == len(PARENT_ARTIFACTS) == 2
        and facts.main_head == claims["main_head"]
        and authority.fixed_authority
        and authority.parent_pin_is_commit
        and authority.parent_ref_and_ancestry
        and parent_blobs_ok
    )

    pairs, landed_psd, here_psd, orders_differ, anchor, involutive, x_trivial = (
        facts.convention
    )
    gate_b = bool(
        pairs == (((4, 4, 0), (4, 0, 4)),
                  ((4, 0, 4), (4, 4, 0)),
                  ((0, 8, 0), (0, 0, 8)))
        and landed_psd
        and here_psd
        and orders_differ == (not claims["lane_conventions_uniform"])
        and all(anchor)
        and len(anchor) == len(TAGS) == 2
        and involutive == (24, 36)
        and x_trivial == (4, 6)
        and facts.exact_no_float
    )

    contrast = dict(facts.contrast)
    null_is_os_positive = any(
        triple[1] == 0 and triple[0] > 0
        for tag in TAGS for triple in contrast[tag]["null_inertias"]
    )
    gate_c = bool(
        all(
            contrast[tag]["framework_w_symbolically_zero"]
            and contrast[tag]["framework_flat"] == FRAMEWORK_FLAT_INERTIA
            and contrast[tag]["framework_live"] == FRAMEWORK_LIVE_INERTIA[tag]
            and contrast[tag]["framework_corner_hollow"]
            == FRAMEWORK_CORNER_HOLLOW[tag]
            and contrast[tag]["framework_doubled"] == FRAMEWORK_DOUBLED_INERTIA
            and contrast[tag]["framework_doubled_identity"]
            and contrast[tag]["rank_c1"] == RANK_C1
            and contrast[tag]["off_region_rank"] == L_X[tag]
            and contrast[tag]["landed_control_trace"] == LANDED_CONTROL_TRACE
            and contrast[tag]["null_unitary"] == NULL_GRID_POINTS
            and contrast[tag]["null_full_rank"] == NULL_GRID_POINTS
            and contrast[tag]["null_doubled_positive"] == NULL_GRID_POINTS
            and contrast[tag]["null_corner_hollow"] == NULL_GRID_POINTS
            and contrast[tag]["null_inertias"] == (NULL_PAIRING_INERTIA,)
            and contrast[tag]["null_identity_at_origin"]
            and contrast[tag]["gram_trace"] == GRAM_TRACE
            and contrast[tag]["grid_points"] == NULL_GRID_POINTS
            for tag in TAGS
        )
        and contrast["12x4"]["null_inertias"] == (claims["null_pairing_inertia"],)
        and null_is_os_positive == claims["unitary_step_is_os_positive"]
        and facts.exact_no_float
    )

    census, corner_by_tag = facts.corner
    corner = dict(corner_by_tag)
    hollow_from = min(
        (t_phys for t_phys, hollow in census if hollow
         and all(h for tt, h in census if tt >= t_phys)),
        default=0,
    )
    corner_holds = all(
        all(row[2] and row[3] for row in corner[tag]["generality"].values())
        and corner[tag]["corner_is_displacement_two"]
        and corner[tag]["even_p_t"]
        for tag in TAGS
    )
    gate_d = bool(
        census == CORNER_T_CENSUS
        and len(census) == 5
        and all(
            corner[tag]["generality"]["herm"][0] == GENERIC_HERM_PARAMS[tag]
            and corner[tag]["generality"]["herm"][1] == GENERIC_HERM_PARAMS[tag]
            and corner[tag]["solve_family_params"] == SOLVE_FAMILY_PARAMS[tag]
            for tag in TAGS
        )
        and (not facts.deep or all(
            corner[tag]["generality"]["free"][1] == GENERIC_FREE_SYMBOLS[tag]
            for tag in TAGS
        ))
        and corner_holds == claims["corner_hollow_at_site_reflections"]
        and hollow_from == claims["corner_hollow_min_t"]
        and facts.exact_no_float
    )

    refutation = dict(facts.refutation)
    # the STRUCK biconditional, measured: is every CONNECTED witness NOT PSD?
    psd_iff_disconnection = all(
        not (row[2] and row[1] > 0)
        for tag in TAGS for row in refutation[tag]["witness_two"]
    ) and all(
        not (refutation[tag]["witness_one"][2]
             and refutation[tag]["witness_one"][0] > 0)
        for tag in TAGS
    )
    dictionary_holds = all(
        refutation[tag]["dictionary"] and refutation[tag]["family_identity"]
        for tag in TAGS
    )
    gate_e = bool(
        all(
            refutation[tag]["lemma"] == LEMMA_RANKS
            and refutation[tag]["witness_one"][:4]
            == (L_X[tag], L_X[tag], True, True)
            and refutation[tag]["witness_one"][4] == WITNESS_PSD_INERTIA
            and tuple(row[1:] for row in refutation[tag]["witness_two"])
            == ((L_X[tag], True, WITNESS_PSD_INERTIA),
                (L_X[tag], True, WITNESS_PSD_INERTIA),
                (L_X[tag], False, WITNESS_NONPSD_INERTIA))
            and refutation[tag]["v_space_dim"] == V_SPACE_REAL_DIM
            and refutation[tag]["cancellation_locus_dim"]
            == CANCELLATION_LOCUS_REAL_DIM
            for tag in TAGS
        )
        and psd_iff_disconnection == claims["psd_iff_disconnection"]
        and dictionary_holds == claims["dictionary_holds"]
        and facts.exact_no_float
    )

    loopholes = dict(facts.loopholes)
    # the census: a route counts as a loophole when it makes the corner LIVE
    routes = 0
    if all(loopholes[tag]["disp2_entries"] == DISP2_CORNER_ENTRIES
           for tag in TAGS):
        routes += 1
    if all(loopholes[tag]["link_generic_live"] > 0 for tag in TAGS):
        routes += 1
    if any(not loopholes[tag]["x_nonlocal_hollow"] for tag in TAGS):
        routes += 1
    gate_f = bool(
        all(
            loopholes[tag]["disp2_entries"] == DISP2_CORNER_ENTRIES
            and loopholes[tag]["disp2_surgical"]
            and (loopholes[tag]["link_generic_live"],
                 loopholes[tag]["link_labels"])
            == LINK_NONHOLLOW_GENERIC[tag]
            and (loopholes[tag]["link_region_live"],
                 loopholes[tag]["link_labels"])
            == LINK_NONHOLLOW_REGION[tag]
            and loopholes[tag]["link_region_psd"] == LINK_PSD_ON_REGION
            and loopholes[tag]["x_nonlocal_hollow"]
            and loopholes[tag]["wider_support_hollow"] == WIDER_SUPPORT_HOLLOW
            for tag in TAGS
        )
        and routes == claims["loophole_count"]
        and facts.exact_no_float
    )

    freezing_by_tag, generator_by_tag, named_by_tag, et_by_tag = facts.freezing
    freezing = dict(freezing_by_tag)
    generators = dict(generator_by_tag)
    named = dict(named_by_tag)
    et_support = dict(et_by_tag)
    future_dead = all(freezing[tag]["future_dead_both_ways"] for tag in TAGS)
    settlement = tuple(
        generators[tag]["settlement_symbolic"] for tag in generators)
    gate_g = bool(
        all(
            freezing[tag]["table_flat"] == FREEZING_TABLE[tag]
            and freezing[tag]["row_dead"]
            and freezing[tag]["column_dead"]
            and freezing[tag]["past_live_both_ways"]
            and freezing[tag]["off_region_forward_rank"] == L_X[tag]
            and not freezing[tag]["action_hermitian"]
            for tag in TAGS
        )
        and all(
            generators[tag]["basis"] == GEN_BASIS_DIM
            and generators[tag]["odd"] == GEN_BASIS_DIM
            and generators[tag]["b_free"] == GEN_BASIS_DIM
            and generators[tag]["live_positions"] == LIVE_POSITIONS
            and generators[tag]["hop_directions"] == HOP_DIRECTIONS
            and generators[tag]["settlement_numeric"] == RANK_SETTLEMENT_NUMERIC
            and generators[tag]["kernel_ratio"] == KERNEL_RATIO[tag]
            and generators[tag]["kernel_witness_inertias"]
            == KERNEL_WITNESS_INERTIA[tag]
            and generators[tag]["hollow_symbolic"]
            == CORNER_CENSUS_SYMBOLIC[tag]
            and generators[tag]["hollow_bench"] == CORNER_CENSUS_BENCH[tag]
            for tag in generators
        )
        and (generators.keys() == set(TAGS) if facts.deep
             else generators.keys() == {"12x4"})
        and all(
            len(named[tag]) == NON_NILPOTENT_NAMED + 1
            and sum(1 for row in named[tag] if not row[1])
            == NON_NILPOTENT_NAMED
            and all(row[3][0] == FRAMEWORK_FLAT_INERTIA for row in named[tag])
            and all(
                triple == FRAMEWORK_LIVE_INERTIA[tag]
                for row in named[tag] if row[2] == RANK_C1
                for triple in row[3][1:]
            )
            and all(
                triple == FRAMEWORK_FLAT_INERTIA
                for row in named[tag] if row[2] == 0
                for triple in row[3]
            )
            for tag in TAGS
        )
        and all(
            et_support[tag]["cover_support"] == ET_COVER_SUPPORT
            and et_support[tag]["cell_entries"] == ET_CELL_ENTRIES
            for tag in TAGS
        )
        and future_dead == claims["future_link_dead_both_ways"]
        and all(row == claims["rank_settlement_symbolic"] for row in settlement)
        and facts.exact_no_float
    )

    required = tuple(claims["required_scope_keys"])
    budget = DEEP_RUNTIME_BUDGET_SEC if facts.deep else RUNTIME_BUDGET_SEC
    gate_h = bool(
        set(facts.scope) == set(required)
        and all(facts.scope[key] for key in required)
        and len(MUTATIONS) == 15
        and len(set(MUTATIONS)) == 15
        and set(MUTATION_GATE) == set(MUTATIONS)
        and set(MUTATION_GATE.values()) == set("ABCDEFGH")
        and N5_FENCE.count("\n") + 1 <= 10
        and N5_FENCE.count("\n") + 1 >= 8
        and POOL_TWO_LEADS == 5
        and elapsed_ns <= budget * 1_000_000_000
    )

    return {"A": gate_a, "B": gate_b, "C": gate_c, "D": gate_d,
            "E": gate_e, "F": gate_f, "G": gate_g, "H": gate_h}


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--mutation", choices=MUTATIONS, default="")
    parser.add_argument(
        "--deep",
        action="store_true",
        help="THE TWO HEAVIES.  (1) the 32-direction cell-local generator basis "
             "at BOTH sizes -- the baseline runs it at 12x4 only, and the "
             "25/32-versus-26/32 corner census at 8x4 is gated only here; and "
             "(2) the FULLY NON-HERMITIAN genericity row at 384 and 576 free "
             "symbols -- the baseline runs the Hermitian row at 192 and 288 "
             "independent real parameters.  The named-generator grid also "
             "widens from two s_t values to six.",
    )
    arguments = parser.parse_args()
    mutation = arguments.mutation
    started_ns = time.monotonic_ns()

    # Every measurement happens once, before any mutation flag is consulted, so
    # a mutation can only rewrite a CLAIM.  No gate can cascade into another
    # because no gate feeds a measurement.
    facts = measure(arguments.deep)
    elapsed_ns = time.monotonic_ns() - started_ns

    raw_gates = evaluate_gates(facts, build_claims(""), elapsed_ns)
